package school.magiccodex.client;
import java.nio.file.Path;import java.util.*;import net.fabricmc.loader.api.FabricLoader;import net.fabricmc.fabric.api.client.screen.v1.*;import net.minecraft.client.MinecraftClient;import net.minecraft.client.gui.DrawContext;import net.minecraft.client.gui.screen.*;import net.minecraft.util.Util;
/** Optional Shift gestures modify screen-space HUD roots while the existing pointer owns input. */
public final class HudCustomization {
 private static final Path PATH=FabricLoader.getInstance().getConfigDir().resolve("magiccodex/hud-layouts.properties");private static final HudLayoutStore STORE=HudLayoutStore.load(PATH);
 private record Drawn(String id,HudLayoutStore.Box base,HudLayoutStore.Box box,long time,long order){}
 private static final Map<String,Drawn> drawn=new HashMap<>();private static long order;private static Frame active;private static Drawn drag;private static double pressX,pressY;private static boolean initialized;
 public static boolean locked(){return STORE.locked();}public static boolean editingGesture(){return !locked()&&HudPointer.active()&&Screen.hasShiftDown();}
 public static void toggle(){cancel();STORE.locked(!STORE.locked());save();SharedNotifications.offer("hud:lock","system",locked()?"HUD 잠금":"HUD 잠금 해제",locked()?"HUD 위치와 크기를 고정했습니다. 채팅 편집은 유지됩니다.":"Ctrl 포인터 또는 채팅에서 Shift+드래그 이동 · Shift+휠 크기 · Shift+우클릭 초기화");}
 public static void reset(){reset(true);}
 public static boolean reset(boolean confirmed){return HudLayoutReset.apply(confirmed,STORE,()->{cancel();drawn.clear();active=null;},()->PlayerHudSettings.get().update(PlayerHudSettings.DEFAULT),()->{boolean saved=STORE.save(PATH);if(!saved)SharedNotifications.offer("hud:save","warning","HUD \uBC30\uCE58 \uC800\uC7A5 \uC2E4\uD328","\uD604\uC7AC \uD654\uBA74\uC5D0\uB9CC \uBC18\uC601\uB418\uC5C8\uC2B5\uB2C8\uB2E4.");return saved;});}
 private static void save(){if(!STORE.save(PATH))SharedNotifications.offer("hud:save","warning","HUD 설정 저장 실패","현재 화면에는 적용됐으나 다음 실행에 보존되지 않을 수 있습니다.");}
 public static void initialize(){if(initialized)return;initialized=true;net.fabricmc.fabric.api.client.networking.v1.ClientPlayConnectionEvents.DISCONNECT.register((handler,client)->{cancel();drawn.clear();active=null;});
 net.fabricmc.fabric.api.client.command.v2.ClientCommandRegistrationCallback.EVENT.register((dispatcher,access)->{var root=net.fabricmc.fabric.api.client.command.v2.ClientCommandManager.literal("HUD");root.then(net.fabricmc.fabric.api.client.command.v2.ClientCommandManager.literal("잠금").executes(ctx->{if(!locked())toggle();return 1;}));root.then(net.fabricmc.fabric.api.client.command.v2.ClientCommandManager.literal("잠금해제").executes(ctx->{if(locked())toggle();return 1;}));root.then(net.fabricmc.fabric.api.client.command.v2.ClientCommandManager.literal("초기화").executes(ctx->{reset();ctx.getSource().sendFeedback(net.minecraft.text.Text.literal("HUD 위치·크기를 초기화했습니다. 채팅창 설정은 유지됩니다."));return 1;}));dispatcher.register(root);});
ScreenEvents.AFTER_INIT.register((client,screen,w,h)->{if(screen instanceof HudCursorScreen||screen instanceof ChatScreen){ScreenMouseEvents.allowMouseClick(screen).register((s,x,y,b)->!press(x,y,b));ScreenMouseEvents.allowMouseRelease(screen).register((s,x,y,b)->!release(b));ScreenMouseEvents.allowMouseScroll(screen).register((s,x,y,dx,dy)->!scroll(x,y,dy));ScreenEvents.remove(screen).register(s->cancel());}});}
 private static int width(){return MinecraftClient.getInstance().getWindow().getScaledWidth();}private static int height(){return MinecraftClient.getInstance().getWindow().getScaledHeight();}
 public static double rawX(){var c=MinecraftClient.getInstance();return c.mouse.getX()*width()/Math.max(1,c.getWindow().getWidth());}public static double rawY(){var c=MinecraftClient.getInstance();return c.mouse.getY()*height()/Math.max(1,c.getWindow().getHeight());}
 public static double[] pointer(double x,double y){return active==null?new double[]{x,y}:inverse(active.drawn,x,y);}
 public static double[] pointer(String id,double x,double y){if(active!=null&&active.drawn.id.equals(id))return new double[]{x,y};var d=drawn.get(id);return d==null?new double[]{x,y}:inverse(d,x,y);}
 private static double[] inverse(Drawn d,double x,double y){double scale=d.box.width()/Math.max(1,d.base.width());return new double[]{d.base.x()+(x-d.box.x())/scale,d.base.y()+(y-d.box.y())/scale};}
 public static Frame begin(DrawContext c,String id,float x,float y,float w,float h){var base=new HudLayoutStore.Box(x,y,Math.max(1,w),Math.max(1,h));if(drag!=null&&drag.id.equals(id)){if(!editingGesture())cancel();else{float scale=drag.box.width()/Math.max(1,drag.base.width());STORE.place(id,base,width(),height(),drag.box.x()+(float)(rawX()-pressX),drag.box.y()+(float)(rawY()-pressY),scale);}}var box=STORE.fit(id,base,width(),height());var d=new Drawn(id,base,box,Util.getMeasuringTimeMs(),++order);drawn.put(id,d);return new Frame(c,d);}
 public static Frame beginHotbar(DrawContext c){var l=PlayerHudLayout.player(width(),height(),PlayerHudSettings.get().percent());float s=l.scale();return begin(c,"hotbar",l.hotbarLeft()*s,(l.hotbarTop()-42)*s,476*s,108*s);}
 public static AutoCloseable beginExternal(Object graphics,String id,float x,float y,float w,float h){return begin((DrawContext)graphics,id,x,y,w,h);}
 public static boolean editingExternal(){return editingGesture();}
 public static float[] screenPoint(float x,float y,float radius){if(active==null)return new float[]{x,y,radius};var d=active.drawn;float scale=d.box.width()/d.base.width();return new float[]{d.box.x()+(x-d.base.x())*scale,d.box.y()+(y-d.base.y())*scale,radius*scale};}
 public static double[] pointerExternal(String id,double x,double y){return pointer(id,x,y);}
 /** Screen box {x,y,w,h} a HUD drew within the last 300 ms, or null. Lets optional mods (Story quest HUD) keep their default spot clear of it. */
 public static float[] recentBoxExternal(String id){var d=drawn.get(id);if(d==null||Util.getMeasuringTimeMs()-d.time>=300)return null;var b=d.box;return new float[]{b.x(),b.y(),b.width(),b.height()};}
 public static final class Frame implements AutoCloseable {private final DrawContext context;private final Drawn drawn;private final Frame previous;private boolean closed;private Frame(DrawContext c,Drawn d){context=c;drawn=d;previous=active;active=this;float s=d.box.width()/d.base.width();c.getMatrices().push();c.getMatrices().translate(d.box.x()-d.base.x()*s,d.box.y()-d.base.y()*s,0);c.getMatrices().scale(s,s,1);}public void close(){if(closed)return;closed=true;context.getMatrices().pop();active=previous;if(editingGesture()){var b=drawn.box;int x=Math.round(b.x()),y=Math.round(b.y()),w=Math.round(b.width()),h=Math.round(b.height());int color=b.contains(rawX(),rawY())?0xD071E5F2:0x6071E5F2;context.fill(x,y,x+w,y+1,color);context.fill(x,y+h-1,x+w,y+h,color);context.fill(x,y,x+1,y+h,color);context.fill(x+w-1,y,x+w,y+h,color);}}}
 private static Drawn hit(double x,double y){long now=Util.getMeasuringTimeMs();return drawn.values().stream().filter(d->now-d.time<300&&d.box.contains(x,y)).max(Comparator.comparingLong(Drawn::order)).orElse(null);}
 public static boolean press(double x,double y,int button){if(!editingGesture())return false;var d=hit(x,y);if(d==null)return false;if(button==1){STORE.reset(d.id);save();return true;}if(button!=0)return false;drag=d;pressX=x;pressY=y;return true;}
 public static boolean release(int button){if(button!=0||drag==null)return false;drag=null;save();return true;}
 public static void cancel(){if(drag!=null){drag=null;save();}}
 public static boolean scroll(double x,double y,double amount){if(!editingGesture()||amount==0)return false;var d=hit(x,y);if(d==null)return false;float scale=d.box.width()/d.base.width();float next=scale*(amount>0?1.08f:1/1.08f);float cx=d.box.x()+d.box.width()/2,cy=d.box.y()+d.box.height()/2;STORE.place(d.id,d.base,width(),height(),cx-d.base.width()*next/2,cy-d.base.height()*next/2,next);save();return true;}
}
